export function maxWindowValues(nums, k) {
    if (k < 1 || k > nums.length)
        return [];
    const q = [], out = [];
    let head = 0;
    for (let i = 0; i < nums.length; i++) {
        while (head < q.length && q[head] <= i - k)
            head++;
        while (q.length > head && nums[q[q.length - 1]] <= nums[i])
            q.pop();
        q.push(i);
        if (i >= k - 1)
            out.push(nums[q[head]]);
    }
    return out;
}
